<script lang="ts">
  import { BookOpen, Check, Pencil, Plus, Power, Trash2, WandSparkles, X } from "lucide-svelte";
  import type { CustomSkill } from "$lib/library-types";
  let { skills, onChange }: { skills:CustomSkill[]; onChange:(skills:CustomSkill[])=>void|Promise<void> }=$props();
  let editor=$state<CustomSkill>();
  const builtIns=[
    {name:"Sprite Director",description:"Routes characters, creatures, effects, packs, and tilesets through the correct production workflow."},
    {name:"AI Frame Polish",description:"Keeps sequential animation frames consistent, crisp, aligned, and loop-ready."},
    {name:"Quality Gates",description:"Checks dimensions, transparency, identity, motion continuity, and export readiness."},
  ];
  function create(){editor={id:`skill-${Date.now().toString(36)}`,name:"",description:"",instructions:"",enabled:true,createdAt:new Date().toISOString()};}
  function edit(skill:CustomSkill){editor={...skill};}
  async function save(){if(!editor?.name.trim()||!editor.instructions.trim())return;const next=skills.some(item=>item.id===editor!.id)?skills.map(item=>item.id===editor!.id?{...editor!,name:editor!.name.trim(),description:editor!.description.trim(),instructions:editor!.instructions.trim()}:item):[{...editor,name:editor.name.trim(),description:editor.description.trim(),instructions:editor.instructions.trim()},...skills];await onChange(next);editor=undefined;}
  async function toggle(skill:CustomSkill){await onChange(skills.map(item=>item.id===skill.id?{...item,enabled:!item.enabled}:item));}
  async function remove(skill:CustomSkill){if(window.confirm(`Delete ${skill.name}?`))await onChange(skills.filter(item=>item.id!==skill.id));}
</script>

<section class="library">
  <header><div><span>LIBRARY</span><h1>Skills</h1><p>Add reusable instructions that guide every generation. Enabled skills are included automatically.</p></div><button class="add" onclick={create}><Plus size={15}/>Add skill</button></header>
  <div class="section-title"><strong>Built in</strong><span>{builtIns.length}</span></div>
  <div class="grid builtins">{#each builtIns as skill}<article><div class="icon"><WandSparkles size={18}/></div><div><h2>{skill.name}</h2><p>{skill.description}</p></div><span class="installed"><Check size={11}/>Installed</span></article>{/each}</div>
  <div class="section-title custom-title"><strong>Your skills</strong><span>{skills.length}</span></div>
  {#if skills.length}<div class="grid">{#each skills as skill}<article class:disabled={!skill.enabled}><div class="icon"><BookOpen size={18}/></div><div><h2>{skill.name}</h2><p>{skill.description||"Custom Sprite Studio instructions"}</p></div><div class="actions"><button onclick={()=>toggle(skill)} title={skill.enabled?"Disable":"Enable"}><Power size={13}/></button><button onclick={()=>edit(skill)} title="Edit"><Pencil size={13}/></button><button onclick={()=>remove(skill)} title="Delete"><Trash2 size={13}/></button></div></article>{/each}</div>{:else}<button class="empty" onclick={create}><WandSparkles size={23}/><strong>Create your first skill</strong><span>Save repeatable instructions for your own production workflow.</span></button>{/if}
</section>

{#if editor}<div class="backdrop" role="presentation" onclick={(event)=>event.target===event.currentTarget&&(editor=undefined)}><form class="dialog" onsubmit={(event)=>{event.preventDefault();save();}}><header><div><span>CUSTOM SKILL</span><h2>{skills.some(item=>item.id===editor?.id)?"Edit skill":"Add skill"}</h2></div><button type="button" onclick={() => editor=undefined}><X size={15}/></button></header><label>Name<input bind:value={editor.name} placeholder="Creature anatomy guard"/></label><label>Description<input bind:value={editor.description} placeholder="What this skill helps with"/></label><label>Instructions<textarea bind:value={editor.instructions} placeholder="Write the exact instructions the AI should follow…"></textarea></label><footer><button type="button" onclick={() => editor=undefined}>Cancel</button><button class="primary" disabled={!editor.name.trim()||!editor.instructions.trim()}>Save skill</button></footer></form></div>{/if}

<style>
  .library{height:100%;overflow:auto;padding:46px clamp(34px,6vw,84px);background:var(--bg)}.library>header{display:flex;align-items:flex-start;justify-content:space-between;gap:30px;padding-bottom:28px;border-bottom:1px solid var(--border)}header span{font-size:9px;letter-spacing:.15em;font-weight:700;color:var(--accent)}h1{font-size:28px;letter-spacing:-.035em;margin:7px 0 8px}header p{font-size:12px;line-height:1.5;color:var(--muted);margin:0;max-width:520px}.add,.primary{height:36px;border:1px solid var(--accent);border-radius:7px;background:var(--accent);color:#111;display:flex;align-items:center;gap:7px;padding:0 12px;font:inherit;font-size:11px;font-weight:650;cursor:pointer}.section-title{height:48px;display:flex;align-items:flex-end;gap:8px;padding-bottom:11px}.section-title strong{font-size:12px}.section-title span{font-size:10px;color:var(--faint)}.custom-title{margin-top:18px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.grid article{min-height:122px;border:1px solid var(--border);border-radius:9px;background:var(--sidebar);padding:15px;display:grid;grid-template-columns:35px minmax(0,1fr);gap:11px;position:relative}.grid article.disabled{opacity:.5}.icon{width:34px;height:34px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--accent);display:grid;place-items:center}.grid h2{font-size:12px;margin:2px 0 6px}.grid p{font-size:10px;line-height:1.5;color:var(--muted);margin:0}.installed{position:absolute;right:10px;bottom:10px;display:flex;align-items:center;gap:4px;color:var(--faint);font-size:9px}.actions{position:absolute;right:8px;bottom:8px;display:flex;gap:2px}.actions button{width:27px;height:27px;border:0;border-radius:5px;background:transparent;color:var(--faint);display:grid;place-items:center;cursor:pointer}.actions button:hover{background:var(--surface);color:var(--text)}.empty{width:100%;min-height:150px;border:1px dashed var(--border-strong);border-radius:9px;background:transparent;color:var(--faint);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;cursor:pointer}.empty strong{color:var(--text);font-size:12px}.empty span{font-size:10px}.backdrop{position:fixed;inset:0;z-index:60;background:#000a;display:grid;place-items:center}.dialog{width:min(520px,calc(100vw - 32px));background:var(--surface);border:1px solid var(--border-strong);border-radius:11px;padding:21px;box-shadow:0 28px 80px #000b}.dialog header{display:flex;justify-content:space-between}.dialog h2{font-size:18px;margin:6px 0 0}.dialog header button{width:28px;height:28px;border:0;border-radius:5px;background:transparent;color:var(--faint);display:grid;place-items:center;cursor:pointer}.dialog label{display:block;font-size:10px;color:var(--muted);margin-top:15px}.dialog input,.dialog textarea{display:block;width:100%;margin-top:6px;border:1px solid var(--border-strong);border-radius:6px;background:var(--bg);color:var(--text);padding:9px;font:inherit;font-size:11px}.dialog input{height:37px}.dialog textarea{height:150px;resize:vertical;line-height:1.5}.dialog footer{display:flex;justify-content:flex-end;gap:7px;margin-top:18px}.dialog footer>button:not(.primary){height:36px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--muted);padding:0 12px;font:inherit;font-size:11px;cursor:pointer}.primary:disabled{opacity:.45}@media(max-width:980px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.grid{grid-template-columns:1fr}}
</style>
